gPz(){return"\u041c\u043e\u0436\u043d\u043e \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0434\u043e 20 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432. \u0412 \u043a\u0430\u0436\u0434\u043e\u043c \u043f\u0440\u043e\u0435\u043a\u0442\u0435 - \u0434\u043e 20 \u0434\u043e\u0441\u043e\u043a, \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u0439 \u0434\u043e\u0441\u043a\u0435 - \u0434\u043e 100 \u0437\u0430\u043c\u0435\u0442\u043e\u043a."},
